def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    def check(H):
        total_hammers_needed = 0
        for h, a in bamboos:
            # After m days of growth without hammering, final height would be:
            current = h
            for _ in range(m):
                current += a
            # Actually we need to consider day by day with hammering
            # But we can compute a greedy approach: keep height <= H
            h_temp = h
            for _ in range(m):
                h_temp += a
                if h_temp > H:
                    h_temp -= p
                    total_hammers_needed += 1
                    if h_temp <= 0:
                        h_temp = 0
                    if total_hammers_needed > k * m:
                        return False
        return True

    if not bamboos:
        return str(0)

    # Find the minimum possible max height using binary search
    # Lower bound: 0, Upper bound: max possible height after m days

    min_height = 0
    max_height = 0
    for h, a in bamboos:
        max_height = max(max_height, h + m * a)

    low = min_height
    high = max_height

    if high <= 0:
        return str(0)

    while low <= high:
        mid = (low + high) >> 1
        if check(mid):
            high = mid - 1
        else:
            low = mid + 1

    return str(low)

