    # max possible difference
    max_d = t * 2 * k

    # current_ways[i] = number of ways to have difference i after current step
    # Difference = (Memory turns) - (Lexa turns)
    # Each turn: Memory adds x in [-k,k], Lexa adds y in [-k,k]
    # Net change: x - y in [-2k, 2k]

    step_changes = []
    for dx in range(-k, k + 1):
        for dy in range(-k, k + 1):
            step_changes.append(dx - dy)

    step_changes.sort()

    curr = {0: 1}
    for _ in range(t):
        new_ways = {}
        for diff, count in curr.items():
            for change in step_changes:
                new_diff = diff + change
                new_ways[new_diff] = (new_ways.get(new_diff, 0) + count) % MOD
        curr = new_ways

    result = 0
    for diff, count in curr.items():
        if a + diff > 0:
            result = (result + count) % MOD

    return f"{result % MOD}\n"

