def solution(data):
    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    segments = []  # Each segment has a set of friends
    current = []

    for i in range(1, n):
        parts = lines[i].split()
        if parts[0] == '1':
            segments.append(current)
            current = []
        else:
            friend = parts[1]
            current.append(friend)
    segments.append(current)

    # Map friend names to IDs 0..m-1
    friends_dict = {}
    friend_list = []
    for s in segments:
        for f in s:
            if f not in friends_dict:
                friends_dict[f] = len(friend_list)
                friend_list.append(f)

    # Reassign IDs up to m-1
    new_dict = {}
    new_list = []
    for f in friend_list:
        new_dict[f] = new_list.index(f) if f in new_list else len(new_list)
        new_list.append(f)
    friends_dict = new_dict
    friend_list = new_list

    # Find actual friends used
    all_friends = set()
    for s in segments:
        all_friends.update(s)
    friend_ids = sorted(all_friends)
    id_map = {f: i for i, f in enumerate(friend_ids)}
    num_friends = len(friend_ids)

    # Build conflict graph
    conflict = [0] * num_friends
    for s in segments:
        mask = 0
        for f in s:
            mask |= 1 << id_map[f]
        conflict[id_map[f]] = (mask | 1 << id_map[f]) - 1

    # Meet-in-the-middle max independent set
    m_left = num_friends // 2
    m_right = num_friends

    def max_independent_set(n):
        if n == 0:
            return 0

        # Split into left and right
        half = n // 2
        left_mask = (1 << half) - 1
        right_mask = ((1 << n) - 1) ^ left_mask

        def count_bits(x):
            c = 0
            while x:
                x &= x - 1
                c += 1
            return c

        left_max = -1
        for s in range(1 << half):
            valid = True
            for i in range(half):
                if (s >> i) & 1:
                    if (conflict[i] & left_mask) & s:
                        valid = False
                        break
            if valid:
                left_max = half if (s & left_mask) == s else left_max

        right_max = -1
        for s in range(1 << (n - half)):
            valid = True
            for i in range(n - half, n):
                if (s >> (i - half)) & 1:
                    if (conflict[i] & right_mask) & s:
                        valid = False
                        break
            if valid:
                right_max = n - half if (s & right_mask) == s else right_max

        return left_max + right_max

    return str(max_independent_set(num_friends))

