        a, b = b, a % b
    return a

def lcm(a, b):
    return a * b // gcd(a, b)

def get_divisors(n):
    divs = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    if n > 1:
        divs.append(n)
    return sorted(divs)

def get_prime_factors(n):
    factors = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = True
            n //= d
        d += 1
    if n > 1:
        factors[n] = True
    return factors

