    # This means: each row in submatrix must have at most one character with odd count
    #             each column in submatrix must have at most one character with odd count

    # Build prefix sums for character counts
    pref = [[[0]*2 for _ in range(n+1)] for _ in range(m+1)]  # pref[r][c][char_idx]

