            var = abs(lit)
            var_clauses[var].append((i, lit))

    assignment = [None] * (m + 1)
    clause_satisfied = [False] * n
    well = set()

    def propagate():
        nonlocal well
        while well:
            lit = well.pop()
            if assignment.get(lit) is None and abs(lit) <= m:
                continue

            var_abs = abs(lit)
            var = lit

            for c_idx, _ in var_clauses[var_abs]:
                if clause_satisfied[c_idx]:
