                        if assignment.get(l, None) is None:
                            assignment[l] = l
                            well.add(l)
                    clause_satisfied[c_idx] = True
                elif assignment.get(l) == l and l != var:
                    assignment[var] = var
                    well.add(var)

    for i in range(n):
        for lit in clauses[i]:
            if assignment.get(lit, None) is None:
                assignment[lit] = lit
                propagate()
                break
        else:
