def dfs_path(u, target, adj):
    """Find path from u to target if possible"""
    path = []
    visited = set()
    stack = [(u, [u])]

    while stack:
        node, cur_path = stack.pop()
        if node == target:
            return cur_path

        if len(cur_path) <= 2 * len(adj):  # Heuristic limit
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append((neighbor, cur_path + [neighbor]))
    return None

