    lines = input_string.strip().split('\n')
    q = int(lines[0])
    queries = []
    for i in range(1, q + 1):
        queries.append(int(lines[i]))

    def get_length(n):
        """Return total length of concatenation of numbers from 1 to n."""
        if n == 0:
            return 0
        length = 0
        for digit in range(1, 19):
            start = 10 ** (digit - 1) if digit > 1 else 1
            end = min(10 ** digit - 1, n)
            if start <= end:
                count = end - start + 1
                length += count * digit
        return length

    def find_digit(k):
        # Find which block contains position k
        block_num = 1
        curr = 0
        while True:
            block_len = get_length(block_num)
            if k - curr <= block_len:
                break
            curr += block_len
            block_num += 1

        # Find which number within block_num contains k-th position (relative to block start)
        pos_in_block = k - curr
        offset = 0  # 0-based index of 1
        num = 1
        while True:
            num_str = str(num)
            num_len = len(num_str)
            if pos_in_block - offset <= num_len:
                break
            offset += num_len
            num += 1

        # Find the specific digit
        num_str = str(num)
        return int(num_str[pos_in_block - offset - 1])

    results = []
    for k in queries:
        digit = find_digit(k)
        results.append(str(digit))

    return '\n'.join(results)

