    class SegTree:
        def __init__(self, n, data, mod):
            self.n = n
            self.data = data
            self.mod = mod
            self.tree = [0] * (4 * n)
            self.lazy = [0] * (4 * n)
            self._build(1, 0, n - 1)

        def _build(self, node, l, r):
            if l == r:
                self.tree[node] = self.data[l] % self.mod
            else:
                mid = (l + r) // 2
                self._build(node * 2, l, mid)
                self._build(node * 2 + 1, mid + 1, r)
                self.tree[node] = (self.tree[node * 2] + self.tree[node * 2 + 1]) % self.mod

        def push(self, node, l, r):
            if self.lazy[node] == 0:
                return
            add = self.lazy[node]
            if l != r:
                self.lazy[node * 2] = (self.lazy[node * 2] + add) % self.mod
                self.lazy[node * 2 + 1] = (self.lazy[node * 2 + 1] + add) % self.mod
            self.tree[node] = (self.tree[node] + add) % self.mod
            self.lazy[node] = 0

