                self.tree[node] = (self.tree[node] + val) % self.mod
                return
            self.push(node, l, r)
            mid = (l + r) // 2
            self.update_range(node * 2, l, mid, ql, qr, val)
            self.update_range(node * 2 + 1, mid + 1, r, ql, qr, val)
            self.tree[node] = (self.tree[node * 2] + self.tree[node * 2 + 1]) % self.mod

