def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(m):
        a, b, e = map(int, lines[i + 1].split())
        edges.append((a, b, e, i))

    # Sort edges by weight
    edges.sort(key=lambda x: x[2])

    # Kruskal's algorithm to build MST
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    mst_edges = set()
    for a, b, e, idx in edges:
        if union(a, b):
            mst_edges.add(idx)

    # Build MST adjacency list
    adj = [[] for _ in range(n + 1)]
    for a, b, e, idx in edges:
        if idx in mst_edges:
            adj[a].append((b, e))
            adj[b].append((a, e))

    # Build binary lifting table
    MAX_L = 20
    UP = [[-1] * (n + 1) for _ in range(MAX_L)]
    MAX_E = [[0] * (n + 1) for _ in range(MAX_L)]

    # DFS traversal to build the table
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        for v, w in adj[u]:
            if not visited[v]:
                visited[v] = True
                depth[v] = depth[u] + 1
                parent_edge[v] = (w, u)
                stack.append(v)

    # Build binary lifting tables using BFS/DFS
    depth = [0] * (n + 1)
    parent_edge = [(-1, -1)] * (n + 1)  # (parent, edge_weight)

    bfs_stack = [1]
    while bfs_stack:
        u = bfs_stack.pop(0)
        for v, w in adj[u]:
            if depth[v] == 0:  # v not visited yet
                depth[v] = depth[u] + 1
                parent_edge[v] = (w, u)
                bfs_stack.append(v)

    for v in range(2, n + 1):
        w, p = parent_edge[v]
        UP[0][v] = p
        MAX_E[0][v] = w

    for i in range(1, MAX_L):
        for v in range(1, n + 1):
            if UP[i - 1][v] != -1:
                UP[i][v] = UP[i - 1][UP[i - 1][v]]
                MAX_E[i][v] = max(MAX_E[i - 1][v], MAX_E[i - 1][UP[i - 1][v]])

    def max_on_path(u, v):
        if u == v:
            return 0
        res = 0
        if depth[u] < depth[v]:
            u, v = v, u

        for i in range(MAX_L - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                res = max(res, MAX_E[i][u])
                u = UP[i][u]

        if u == v:
            return res

        for i in range(MAX_L - 1, -1, -1):
            if UP[i][u] != UP[i][v]:
                res = max(res, MAX_E[i][u])
                res = max(res, MAX_E[i][v])
                u = UP[i][u]
                v = UP[i][v]

        res = max(res, MAX_E[0][u])
        res = max(res, MAX_E[0][v])
        return res

    results = []
    for a, b, e, idx in edges:
        if idx not in mst_edges:
            results.append(str(max_on_path(a, b)))

    return '\n'.join(results)

