        '2': (0, 3),  # Top, Right
        '3': (1, 2),  # Bottom, Left
        '4': (1, 3),  # Bottom, Right
    }

    def has_leak():
        # Check internal connections (not on border)
        for r in range(n):
            for c in range(m):
                if grid[r][c] == '.':
                    continue
                ends = pipe_ends[grid[r][c]]
                if ends[0] == 0:  # Top end
                    if r == 0:  # border - OK
                        continue
                    if not (grid[r-1][c] != '.' and pipe_ends[grid[r-1][c]][0] == 1):
                        return True  # leak
                if ends[1] == 0:  # Bottom end
                    if r == n-1:  # border - OK
                        continue
                    if not (grid[r+1][c] != '.' and pipe_ends[grid[r+1][c]][1] == 0):
                        return True  # leak
                if ends[2] == 0:  # Left end
                    if c == 0:  # border - OK
                        continue
                    if not (grid[r][c-1] != '.' and pipe_ends[grid[r][c-1]][2] == 3):
